mapper.select:
select * from b_xiecheng_data where status =1 and push_status =2 and sha256_tel = #{cell} and api_code in
#{apiCode}
and create_time > str_to_date(now(), '%Y-%m-%d')

select
  *
from b_xiecheng_data
where  create_date =#{createDate} and local_id not in (2242481,2242482,2272503)

  and local_id > #{minlocalId}

order by local_id limit 5000;

select id,local_id as localId
from b_xiecheng_data
where create_time >= #{createTime}
  and push_status =1 and status =1

  and id > #{id}

order by id limit 5000;

select count(distinct sha256_tel)
from b_xiecheng_data
where  create_time >=#{requestData} and create_time < #{endData} 
  and push_status = 2 and status = 1

  and api_code = #{apiCode}

select count(distinct a.sha256_tel)
from b_xiecheng_data as a left join b_marketing_transfer_sync_#{cid} as b
on a.sha256_tel = b.cust_num
where b.request_data =#{requestData}
  and a.push_status = 2 and a.status = 1
  and  a.create_time >=#{requestData} and a.create_time < #{endData} 

  and b.api_code = #{apiCode}
  and a.api_code = #{apiCode}


  and b.reserve_field1 ->'$.convType'=#{convType}
